import java.util.*;

public class Main {
    int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {                             // for every output position
            long product = 1;
            for (int j = 0; j < n; j++) {                           // multiply in every other value
                if (j != i) product *= nums[j];
            }
            answer[i] = (int) product;
        }
        return answer;
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3, 4};
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.productExceptSelf(nums)));
    }
}

